insert into public.products (id, tenant_id, category_id, name, description, price, image, is_chef, is_veg, is_gf, is_popular, available, ingredients, modifiers, pairing, details, sort_order) values ('00000000-0000-4000-8000-000000000001', 'a0000000-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000003', 'Burger Trufada Gourmet', 'Carne 100% Angus (200g), queso brie fundido, mayonesa de trufa negra y cebolla caramelizada.', 34000, 'https://images.unsplash.com/photo-1568901346375-23c9450c58cd?w=800&auto=format&fit=crop', true, false, false, true, true, array['Carne Angus 200g', 'Queso Brie', 'Trufa Negra', 'Cebolla Caramelizada', 'Pan Brioche Artesanal']::text[], '[{"title":"Término de la Carne","required":true,"options":[{"name":"Término Medio","price":0},{"name":"Tres Cuartos","price":0},{"name":"Bien Cocida","price":0}]},{"title":"Adicionales Gourmet","required":false,"options":[{"name":"Tocineta Cincelada Crujiente","price":4500},{"name":"Queso Brie Extra","price":5000},{"name":"Huevo de Campo Estrellado","price":3000}]}]'::jsonb, '{"productId":"00000000-0000-4000-8000-000000000007","description":"El balance cítrico y taninos suaves limpian el paladar tras la intensidad de la trufa."}'::jsonb, '{"rating":4.9,"reviewsCount":184,"prepTime":"15-20 min","spicyLevel":0,"calories":"720 kcal","chefNotes":"Recomendamos el término medio para apreciar la jugosidad del corte Angus y el aroma de la trufa."}'::jsonb, 0) on conflict (id) do nothing;
insert into public.products (id, tenant_id, category_id, name, description, price, image, is_chef, is_veg, is_gf, is_popular, available, ingredients, modifiers, pairing, details, sort_order) values ('00000000-0000-4000-8000-000000000002', 'a0000000-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000001', 'Tacos de Camarón al Pastor', 'Tres tortillas artesanales, camarones en marinada al pastor, piña asada y emulsión de aguacate.', 28000, 'https://images.unsplash.com/photo-1551504734-5ee1c4a1479b?w=800&auto=format&fit=crop', true, false, true, true, true, array['Camarones de cultivo sostenible', 'Piña miel asada', 'Cilantro fresco', 'Emulsión de aguacate Hass', 'Tortillas de maíz nixtamalizado']::text[], '[{"title":"Nivel de Picante","required":false,"options":[{"name":"Picante Ligero","price":0},{"name":"Picante Medio (Original)","price":0},{"name":"Picante Alto (Habanero)","price":1500}]}]'::jsonb, '{"productId":"00000000-0000-4000-8000-000000000005","description":"La frescura del coco aplaca suavemente el picante del adobo al pastor."}'::jsonb, '{"rating":4.8,"reviewsCount":132,"prepTime":"12-15 min","spicyLevel":2,"calories":"450 kcal","chefNotes":"La piña tatemada al carbón equilibra el toque picante del adobo tradicional de guajillo."}'::jsonb, 1) on conflict (id) do nothing;
insert into public.products (id, tenant_id, category_id, name, description, price, image, is_chef, is_veg, is_gf, is_popular, available, ingredients, modifiers, pairing, details, sort_order) values ('00000000-0000-4000-8000-000000000003', 'a0000000-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000002', 'Bowl Mediterráneo Vegano', 'Quinoa real, garbanzos tostados con paprika, aguacate, pepino, hummus artesanal y aderezo tahini.', 29000, 'https://images.unsplash.com/photo-1540420773420-3366772f4999?w=800&auto=format&fit=crop', false, true, true, false, true, array['Quinoa tricolor', 'Hummus de garbanzo', 'Aguacate', 'Tomates cherry', 'Semillas de chía y sésamo']::text[], '[{"title":"Proteína Extra","required":false,"options":[{"name":"Tofu Marinado a la Plancha","price":4000},{"name":"Champiñones Portobello Asados","price":4500}]}]'::jsonb, '{"productId":"00000000-0000-4000-8000-000000000005","description":"Acompañamiento refrescante con extracto de menta fresca."}'::jsonb, '{"rating":4.7,"reviewsCount":96,"prepTime":"10-12 min","spicyLevel":0,"calories":"380 kcal","chefNotes":"Rico en proteína vegetal de alto valor biológico y grasas saludables insaturadas."}'::jsonb, 2) on conflict (id) do nothing;
insert into public.products (id, tenant_id, category_id, name, description, price, image, is_chef, is_veg, is_gf, is_popular, available, ingredients, modifiers, pairing, details, sort_order) values ('00000000-0000-4000-8000-000000000004', 'a0000000-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000002', 'Ojo de Bife 300g Importado', 'Corte madurado a la parrilla de carbón, servido con papas rústicas al romero y chimichurri casero.', 62000, 'https://images.unsplash.com/photo-1544025162-d76694265947?w=800&auto=format&fit=crop', true, false, true, true, true, array['Ribeye / Ojo de Bife 300g', 'Papas rústicas', 'Romero fresco', 'Chimichurri de la casa']::text[], '[{"title":"Término del Corte","required":true,"options":[{"name":"Término Medio (Recomendado Chef)","price":0},{"name":"Tres Cuartos","price":0},{"name":"Bien Asado","price":0},{"name":"Azul / Sangrante","price":0}]},{"title":"Guarnición Adicional","required":false,"options":[{"name":"Espárragos Salteados a la Mantequilla","price":7000},{"name":"Puré de Papa Trufado","price":6500}]}]'::jsonb, '{"productId":"00000000-0000-4000-8000-000000000007","description":"Maridaje sublime que realza las notas ahumadas del asado a la parrilla."}'::jsonb, '{"rating":5,"reviewsCount":245,"prepTime":"20-25 min","spicyLevel":0,"calories":"850 kcal","chefNotes":"Corte con marmoleo premium grado 5+, sazonado únicamente con sal marina en escamas y pimienta negra recién molida."}'::jsonb, 3) on conflict (id) do nothing;
insert into public.products (id, tenant_id, category_id, name, description, price, image, is_chef, is_veg, is_gf, is_popular, available, ingredients, modifiers, pairing, details, sort_order) values ('00000000-0000-4000-8000-000000000005', 'a0000000-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000004', 'Limonada de Coco Frappé', 'Crema de coco natural, zumo de limón fresco exprimido y hielo frappé batido con toque de menta.', 12000, 'https://images.unsplash.com/photo-1513558161293-cdaf765ed2fd?w=800&auto=format&fit=crop', false, true, true, true, true, array['Leche de coco cremosa', 'Limón Tahití fresco', 'Hielo cristal', 'Menta fresca']::text[], '[{"title":"Endulzante","required":false,"options":[{"name":"Tradicional (Azúcar de Caña)","price":0},{"name":"Endulzado con Stevia","price":0},{"name":"Sin Azúcar Añadido","price":0}]}]'::jsonb, null, '{"rating":4.9,"reviewsCount":178,"prepTime":"5-8 min","spicyLevel":0,"calories":"210 kcal","chefNotes":"Preparada al instante sin conservantes ni jarabes artificiales."}'::jsonb, 4) on conflict (id) do nothing;
insert into public.products (id, tenant_id, category_id, name, description, price, image, is_chef, is_veg, is_gf, is_popular, available, ingredients, modifiers, pairing, details, sort_order) values ('00000000-0000-4000-8000-000000000006', 'a0000000-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000005', 'Tiramisú Tradicional Artesanal', 'Bizcocho savoiardi embebido en café espresso, licor de amaretto y suave crema mascarpone espolvoreada con cacao.', 18000, 'https://images.unsplash.com/photo-1571877227200-a0d98ea607e9?w=800&auto=format&fit=crop', false, false, false, true, true, array['Queso Mascarpone', 'Savoiardi italianos', 'Café Espresso especial', 'Cacao puro 70%', 'Amaretto Disaronno']::text[], '[]'::jsonb, null, '{"rating":4.9,"reviewsCount":154,"prepTime":"5 min","spicyLevel":0,"calories":"420 kcal","chefNotes":"Receta italiana clásica de Treviso, con cacao amargo al 70% de origen colombiano."}'::jsonb, 5) on conflict (id) do nothing;
insert into public.products (id, tenant_id, category_id, name, description, price, image, is_chef, is_veg, is_gf, is_popular, available, ingredients, modifiers, pairing, details, sort_order) values ('00000000-0000-4000-8000-000000000007', 'a0000000-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000004', 'Sangría Artesanal de Frutos Rojos', 'Vino tinto joven infusionado con fresas, moras, arándanos silvestres, toque de canela y licor de naranja.', 16000, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=800&auto=format&fit=crop', true, true, true, true, true, array['Vino Tinto Reserva', 'Mix de Frutos Rojos', 'Cointreau', 'Rodajas de Naranja y Canela']::text[], '[]'::jsonb, null, '{"rating":4.9,"reviewsCount":110,"prepTime":"5 min","spicyLevel":0,"calories":"180 kcal","chefNotes":"Macerada en frío por 24 horas para extraer toda la esencia frutal."}'::jsonb, 6) on conflict (id) do nothing;
insert into public.products (id, tenant_id, category_id, name, description, price, image, is_chef, is_veg, is_gf, is_popular, available, ingredients, modifiers, pairing, details, sort_order) values ('00000000-0000-4000-8000-000000000008', 'a0000000-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000001', 'Burrata Pugliese con Pesto y Prosciutto', 'Queso burrata fresco artesanal de 150g, láminas de jamón de Parma, tomates confitados y pesto de albahaca fresca.', 36000, 'https://images.unsplash.com/photo-1592417817098-8f3d6eb22a45?w=800&auto=format&fit=crop', true, false, true, true, true, array['Burrata de búfala 150g', 'Prosciutto di Parma', 'Pesto genovés con piñones', 'Tomates cherry', 'Tomates cherry confitados', 'Aceite de oliva extra virgen']::text[], '[{"title":"Acompañamiento de Pan","required":false,"options":[{"name":"Focaccia al Romero recién horneada","price":4000},{"name":"Tostadas Sin Gluten","price":3500}]}]'::jsonb, '{"productId":"00000000-0000-4000-8000-000000000007","description":"El toque frutal resalta la salinidad del prosciutto y la frescura de la albahaca."}'::jsonb, '{"rating":5,"reviewsCount":201,"prepTime":"8-10 min","spicyLevel":0,"calories":"530 kcal","chefNotes":"Servida a temperatura ambiente para permitir que el corazón de stracciatella fluya cremosamente."}'::jsonb, 7) on conflict (id) do nothing;
insert into public.products (id, tenant_id, category_id, name, description, price, image, is_chef, is_veg, is_gf, is_popular, available, ingredients, modifiers, pairing, details, sort_order) values ('00000000-0000-4000-8000-000000000009', 'a0000000-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000002', 'Risotto al Tartufo Nero & Funghi Porcini', 'Arroz Carnaroli mantecado con mantequilla de trufa de Umbría, setas porcini silvestres, láminas de trufa negra fresca y queso Parmigiano Reggiano 24 meses.', 48000, '/dishes/risotto.jpg', true, true, true, true, true, array['Arroz Carnaroli', 'Setas Porcini silvestres', 'Mantequilla de Trufa Negra', 'Parmigiano Reggiano 24m', 'Vino Blanco Pinot Grigio']::text[], '[{"title":"Adicional de Lujo","required":false,"options":[{"name":"Láminas extra de Trufa Negra","price":9000},{"name":"Colas de Langostinos Salteados","price":12000}]}]'::jsonb, '{"productId":"00000000-0000-4000-8000-000000000007","description":"Los taninos y frutos rojos equilibran la untuosidad del queso y la intensidad de la trufa."}'::jsonb, '{"rating":5,"reviewsCount":168,"prepTime":"18-22 min","spicyLevel":0,"calories":"590 kcal","chefNotes":"Cocinamos el arroz lentamente con caldo de verduras rostizadas y emulsionamos con Parmigiano de 24 meses."}'::jsonb, 8) on conflict (id) do nothing;
insert into public.products (id, tenant_id, category_id, name, description, price, image, is_chef, is_veg, is_gf, is_popular, available, ingredients, modifiers, pairing, details, sort_order) values ('00000000-0000-4000-8000-000000000010', 'a0000000-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000002', 'Salmón Glaseado en Costra de Pistacho', 'Filete de salmón noruego con costra crocante de pistacho siciliano, puré sedoso de coliflor al azafrán y reducción de cítricos y miel silvestre.', 54000, '/dishes/salmon.jpg', true, false, true, true, true, array['Salmón Noruego Fresco', 'Pistachos de Sicilia', 'Puré de Coliflor al Azafrán', 'Reducción de Cítricos', 'Microvegetales']::text[], '[{"title":"Término del Salmón","required":true,"options":[{"name":"Término Medio Rosado (Recomendado)","price":0},{"name":"Bien Cocido","price":0}]}]'::jsonb, '{"productId":"00000000-0000-4000-8000-000000000018","description":"El frescor floral del saúco resalta la untuosidad de las grasas nobles del salmón."}'::jsonb, '{"rating":4.9,"reviewsCount":142,"prepTime":"16-20 min","spicyLevel":0,"calories":"520 kcal","chefNotes":"Sellado a fuego vivo para mantener la terneza y jugosidad interior rosada."}'::jsonb, 9) on conflict (id) do nothing;
insert into public.products (id, tenant_id, category_id, name, description, price, image, is_chef, is_veg, is_gf, is_popular, available, ingredients, modifiers, pairing, details, sort_order) values ('00000000-0000-4000-8000-000000000011', 'a0000000-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000002', 'Ravioli Neri di Aragosta al Zafferano', 'Pasta negra artesanal con tinta de calamar, rellena de langosta del Caribe y ricotta fresca en emulsión de mantequilla avellanada al azafrán y caviar Oscietra.', 52000, '/dishes/ravioli.jpg', true, false, false, true, true, array['Pasta fresca con tinta de calamar', 'Langosta caribeña', 'Ricotta de búfala', 'Azafrán en hebras', 'Caviar Oscietra']::text[], '[{"title":"Topping de Autor","required":false,"options":[{"name":"Perlas de Caviar Oscietra Extra","price":14000},{"name":"Queso Parmigiano Rallado al Momento","price":4000}]}]'::jsonb, '{"productId":"00000000-0000-4000-8000-000000000017","description":"Aromas a madera ahumada que contrastan soberbiamente con el azafrán."}'::jsonb, '{"rating":5,"reviewsCount":189,"prepTime":"15-18 min","spicyLevel":0,"calories":"610 kcal","chefNotes":"Masa estirada a mano cada mañana, con relleno de colas de langosta flameadas en coñac."}'::jsonb, 10) on conflict (id) do nothing;
insert into public.products (id, tenant_id, category_id, name, description, price, image, is_chef, is_veg, is_gf, is_popular, available, ingredients, modifiers, pairing, details, sort_order) values ('00000000-0000-4000-8000-000000000012', 'a0000000-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000001', 'Carpaccio di Wagyu A5 con Tartufo', 'Finas láminas de res Wagyu A5 japonés marmoleado, lascas de Parmigiano Reggiano, microalbahaca, perlas de balsámico di Modena y aceite de trufa blanca.', 46000, '/dishes/carpaccio.jpg', true, false, true, true, true, array['Corte Wagyu A5 certificado', 'Parmigiano Reggiano 24m', 'Aceite de Trufa Blanca de Alba', 'Perlas de Aceto Balsámico', 'Rúgula selvática']::text[], '[{"title":"Pan de Acompañamiento","required":false,"options":[{"name":"Focaccia crocante recién horneada","price":4000},{"name":"Tostaditas de Centeno y Sal Marina","price":3500}]}]'::jsonb, '{"productId":"00000000-0000-4000-8000-000000000007","description":"La acidez frutal balancea la grasa intramuscular marmolada del Wagyu."}'::jsonb, '{"rating":4.9,"reviewsCount":215,"prepTime":"8-10 min","spicyLevel":0,"calories":"390 kcal","chefNotes":"Carne cortada a -2°C para conservar su textura de seda que se funde inmediatamente al paladar."}'::jsonb, 11) on conflict (id) do nothing;
insert into public.products (id, tenant_id, category_id, name, description, price, image, is_chef, is_veg, is_gf, is_popular, available, ingredients, modifiers, pairing, details, sort_order) values ('00000000-0000-4000-8000-000000000013', 'a0000000-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000002', 'Pulpo Braseado al Carbón de Encina', 'Tentáculo de pulpo del Pacífico caramelizado a las brasas, sobre crema tibia de papas criollas al pimentón de la Vera, chips de ajo y aceite de oliva virgen extra.', 58000, '/dishes/octopus.jpg', true, false, true, true, true, array['Tentáculo de Pulpo', 'Papa criolla andina', 'Pimentón ahumado de la Vera', 'Ajo confitado', 'Sal Maldón en escamas']::text[], '[]'::jsonb, '{"productId":"00000000-0000-4000-8000-000000000005","description":"El toque cremoso y cítrico refresca las notas ahumadas del carbón de encina."}'::jsonb, '{"rating":4.9,"reviewsCount":176,"prepTime":"15-20 min","spicyLevel":1,"calories":"470 kcal","chefNotes":"Cocción al vacío a 77°C durante 5 horas antes de terminar en parrilla de hierro al carbón."}'::jsonb, 12) on conflict (id) do nothing;
insert into public.products (id, tenant_id, category_id, name, description, price, image, is_chef, is_veg, is_gf, is_popular, available, ingredients, modifiers, pairing, details, sort_order) values ('00000000-0000-4000-8000-000000000014', 'a0000000-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000002', 'Gnocchi al Pesto di Pistacchio e Gamberi', 'Ñoquis de papa hechos a mano con pesto cremoso de pistacho de Bronte, camarones jumbo sellados al fuego, stracciatella fresca y flores comestibles.', 49000, '/dishes/gnocchi.jpg', true, false, false, true, true, array['Ñoquis caseros de papa', 'Camarones jumbo', 'Pesto de pistacho de Bronte', 'Stracciatella cremosa', 'Flores de borraja']::text[], '[{"title":"Porción Extra","required":false,"options":[{"name":"Camarones Jumbo Adicionales (3 uds)","price":9000},{"name":"Extra Stracciatella de Búfala","price":5000}]}]'::jsonb, '{"productId":"00000000-0000-4000-8000-000000000018","description":"Frescura botánica que complementa el dulzor de los camarones y el pistacho."}'::jsonb, '{"rating":4.8,"reviewsCount":124,"prepTime":"12-16 min","spicyLevel":0,"calories":"640 kcal","chefNotes":"Gnocchi esponjosos como nubes preparados diariamente con papas asadas a la sal."}'::jsonb, 13) on conflict (id) do nothing;
insert into public.products (id, tenant_id, category_id, name, description, price, image, is_chef, is_veg, is_gf, is_popular, available, ingredients, modifiers, pairing, details, sort_order) values ('00000000-0000-4000-8000-000000000015', 'a0000000-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000002', 'Costillar de Cordero en Costra de Hierbas', 'Chop de cordero lechal asado a término medio con costra dorada de hierbas provenzales, demi-glace al romero fresco, zanahorias baby glaseadas y puré trufado.', 68000, '/dishes/lamb.jpg', true, false, false, true, true, array['Costillar de Cordero', 'Hierbas de Provenza y Panko', 'Demi-glace al Romero', 'Zanahorias glaseadas con miel', 'Puré trufado']::text[], '[{"title":"Término de Cocción","required":true,"options":[{"name":"Término Medio Rosado (Sugerido)","price":0},{"name":"Tres Cuartos","price":0},{"name":"Bien Cocido","price":0}]}]'::jsonb, '{"productId":"00000000-0000-4000-8000-000000000017","description":"El roble y los aromas del bourbon hacen sinergia perfecta con la potencia del cordero."}'::jsonb, '{"rating":5,"reviewsCount":198,"prepTime":"20-25 min","spicyLevel":0,"calories":"780 kcal","chefNotes":"Carne tierna y jugosa con demi-glace reducida durante 36 horas con huesos tostados y Oporto."}'::jsonb, 14) on conflict (id) do nothing;
insert into public.products (id, tenant_id, category_id, name, description, price, image, is_chef, is_veg, is_gf, is_popular, available, ingredients, modifiers, pairing, details, sort_order) values ('00000000-0000-4000-8000-000000000016', 'a0000000-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000001', 'Tartare Nikkei de Atún Bluefin', 'Dados de atún rojo Bluefin grado sashimi marinados en ponzu trufado, mousse de aguacate Hass, mango biche, sésamo tostado y esferas de yuzu cítrico.', 44000, '/dishes/tuna.jpg', true, false, true, true, true, array['Atún Rojo Bluefin', 'Mousse de Aguacate Hass', 'Mango Biche', 'Salsa Ponzu artesanal', 'Perlas de Yuzu']::text[], '[{"title":"Picante Nikkei","required":false,"options":[{"name":"Normal (Toque Sutil de Rocoto)","price":0},{"name":"Intenso (Con Wasabi y Shichimi)","price":1000},{"name":"Sin Picante","price":0}]}]'::jsonb, '{"productId":"00000000-0000-4000-8000-000000000018","description":"Maridaje cítrico y refrescante que enaltece el sabor limpio del atún crudo."}'::jsonb, '{"rating":4.9,"reviewsCount":153,"prepTime":"10 min","spicyLevel":1,"calories":"360 kcal","chefNotes":"Atún fresco de pesca responsable servido sobre hielo picado para máxima frescura."}'::jsonb, 15) on conflict (id) do nothing;
insert into public.products (id, tenant_id, category_id, name, description, price, image, is_chef, is_veg, is_gf, is_popular, available, ingredients, modifiers, pairing, details, sort_order) values ('00000000-0000-4000-8000-000000000017', 'a0000000-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000004', 'Smoked Old Fashioned de Autor', 'Bourbon añejado 12 años, bitter aromático artesanal, sirope de panela orgánica infusionada en pieles de naranja y humo de maderas de cerezo servido bajo campana.', 26000, '/dishes/cocktail.jpg', true, true, true, true, true, array['Bourbon Single Barrel 12 años', 'Bitter Angostura & Naranja', 'Sirope de Panela & Clavos', 'Cáscara de Naranja flameada', 'Humo de Cerezo']::text[], '[]'::jsonb, null, '{"rating":5,"reviewsCount":230,"prepTime":"5-7 min","spicyLevel":0,"calories":"190 kcal","chefNotes":"Ahumado al instante frente a la mesa con virutas de cerezo silvestre y hielo cristalino de corte manual."}'::jsonb, 16) on conflict (id) do nothing;
insert into public.products (id, tenant_id, category_id, name, description, price, image, is_chef, is_veg, is_gf, is_popular, available, ingredients, modifiers, pairing, details, sort_order) values ('00000000-0000-4000-8000-000000000018', 'a0000000-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000004', 'Elixir Botánico de Saúco & Pepino', 'Mocktail premium con destilado botánico sin alcohol, cordial de flor de saúco, láminas de pepino fresco, tónica artesanal y escamas de oro comestible de 24k.', 18000, '/dishes/elderflower.jpg', false, true, true, true, true, array['Destilado botánico de enebro sin alcohol', 'Cordial de Flor de Saúco Saint-Germain', 'Pepino orgánico', 'Agua Tónica Premium', 'Oro 24k comestible']::text[], '[]'::jsonb, null, '{"rating":4.8,"reviewsCount":97,"prepTime":"5 min","spicyLevel":0,"calories":"120 kcal","chefNotes":"Bebida elegante, aromática y digestiva servida en copa de cristal tallado."}'::jsonb, 17) on conflict (id) do nothing;
insert into public.products (id, tenant_id, category_id, name, description, price, image, is_chef, is_veg, is_gf, is_popular, available, ingredients, modifiers, pairing, details, sort_order) values ('00000000-0000-4000-8000-000000000019', 'a0000000-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000005', 'Tarta Vasca de Queso & Pistacho de Bronte', 'Cheesecake horneado al estilo Donostia con corazón fundente y cremoso, pasta pura de pistachos sicilianos tostados, frambuesas silvestres y crumble de mantequilla.', 22000, '/dishes/cheesecake.jpg', true, false, false, true, true, array['Queso Crema San Millán', 'Pistachos de Bronte D.O.P.', 'Huevos de campo', 'Frambuesas frescas', 'Crumble artesanal']::text[], '[]'::jsonb, '{"productId":"00000000-0000-4000-8000-000000000017","description":"El ahumado del cóctel potencia el tostado exterior de la tarta vasca."}'::jsonb, '{"rating":5,"reviewsCount":310,"prepTime":"5 min","spicyLevel":0,"calories":"490 kcal","chefNotes":"Horneada a alta temperatura para lograr la superficie tostada caramelizada y un centro líquido y sedoso."}'::jsonb, 18) on conflict (id) do nothing;
insert into public.products (id, tenant_id, category_id, name, description, price, image, is_chef, is_veg, is_gf, is_popular, available, ingredients, modifiers, pairing, details, sort_order) values ('00000000-0000-4000-8000-000000000020', 'a0000000-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000005', 'Volcán de Chocolate Belga 70% & Vainilla', 'Coulant tibio de chocolate amargo belga Callebaut con centro de lava derretida, helado artesanal de vainilla Bourbon de Madagascar y tierra crocante de avellanas.', 24000, '/dishes/volcan.jpg', true, false, false, true, true, array['Chocolate Belga Callebaut 70%', 'Mantequilla francesa sin sal', 'Helado de Vainilla Bourbon artesanal', 'Avellanas del Piamonte tostadas']::text[], '[{"title":"Bola Extra de Helado","required":false,"options":[{"name":"Vainilla Bourbon de Madagascar","price":4500},{"name":"Helado de Pistacho Siciliano","price":5500}]}]'::jsonb, '{"productId":"00000000-0000-4000-8000-000000000007","description":"El maridaje de vino tinto y chocolate negro eleva los matices frutales y achocolatados."}'::jsonb, '{"rating":5,"reviewsCount":284,"prepTime":"10 min","spicyLevel":0,"calories":"540 kcal","chefNotes":"Servido caliente al instante del horno para asegurar la caída perfecta del chocolate líquido."}'::jsonb, 19) on conflict (id) do nothing;
